INSERT INTO settings(id,data) VALUES(1,'{"title":"Ride For Brains","edition":"2e édition","date":"2027-08-21","eventAt":"2027-08-21T07:30:00-04:00","reception":"07:30","closing":null,"location":null,"contact":"thomasberu0104@hotmail.com","donationUrl":"https://braincanada.akaraisin.com/ui/commencerlacollecte/p/91773d9e68194eb39aed1eaec3ad88a0","registrationOpen":false,"salesOpenAt":null,"salesCloseAt":null,"minimumAge":18,"refundDays":15,"taxMode":"unconfirmed","termsVersion":"2026-10-29-brouillon","legalApproved":false,"brandApproved":false,"editableFields":["phone","emergency_name","emergency_phone"],"terms":"Brouillon à valider. Participation réservée aux personnes de 18 ans et plus. Prix affichés en dollars canadiens. Un remboursement complet peut être demandé à 15 jours ou plus du début de l’événement. À moins de 15 jours : aucun remboursement. Les dons faits directement à Brain Canada sont distincts des inscriptions. Les règles en cas d’annulation ou de report de l’événement restent à définir.","privacy":"Brouillon à valider. Les données servent à gérer les inscriptions, les paiements, la sécurité et l’accueil. Ride For Brains utilise Cloudflare, Stripe et le prestataire de courriel configuré. Les coordonnées d’urgence sont limitées au personnel autorisé. Responsable : Thomas, thomasberu0104@hotmail.com. La durée de conservation, les modalités de suppression et les transferts de données restent à valider avant ouverture.","cause":"Ride For Brains est un événement sportif caritatif organisé par son équipe. Les dons sont effectués sur la plateforme de collecte de Brain Canada. Les inscriptions sont gérées par Ride For Brains.","story":"Thomas, François-Xavier et Sammy réunissent le vélo, la course et la marche autour d’une même cause. Pour cette deuxième édition, chaque kilomètre est une façon de se rassembler et de soutenir la recherche sur le cerveau.","faq":[{"q":"À qui s’adresse l’événement?","a":"La participation est réservée aux personnes de 18 ans et plus."},{"q":"Combien coûte une inscription?","a":"Le tarif de départ est de 15 $ CA par activité. Les dons à Brain Canada se font séparément."},{"q":"Où se déroulera l’événement?","a":"Le lieu de départ et les parcours seront annoncés après confirmation par l’organisation."},{"q":"Puis-je annuler mon inscription?","a":"Remboursement complet à 15 jours ou plus de l’événement. Aucun remboursement à moins de 15 jours. La demande se fait dans votre espace participant."}],"partners":[],"photos":[]}');
